/* ============================================================
   15. minimap
   ============================================================ */
const mm = document.getElementById('mmc');
const mctx = mm.getContext('2d');
const MM_W = mm.width, MM_H = mm.height;
const MM = {x0:CITY_BOX.min.x-8, x1:CITY_BOX.max.x+8, z0:CITY_BOX.min.z-8, z1:CITY_BOX.max.z+8};
function mx(x){ return (x-MM.x0)/(MM.x1-MM.x0)*MM_W; }
function mz(z){ return (z-MM.z0)/(MM.z1-MM.z0)*MM_H; }

/* colours follow each district's own `color` — no second list to maintain */
const MM_FILL = Object.fromEntries(DISTRICTS.map(d => [d.id, hex6(d.color)]));
function drawMinimap(){
  mctx.clearRect(0,0,MM_W,MM_H);
  mctx.fillStyle = '#FAFBFB'; mctx.fillRect(0,0,MM_W,MM_H);

  // flow spine
  mctx.strokeStyle='rgba(43,45,48,.10)'; mctx.lineWidth=7;
  mctx.beginPath(); mctx.moveTo(mx(-80),mz(0)); mctx.lineTo(mx(90),mz(0)); mctx.stroke();

  DISTRICTS.forEach(d=>{
    const x=mx(d.x0), y=mz(d.z0), w=mx(d.x1)-mx(d.x0), h=mz(d.z1)-mz(d.z0);
    /* PLAN is where an empty plot should read best: keep the outline, drop the
       fill. menu.js decides which stage is the one to build next. */
    if(GAME.on && !GAME.built.has(d.id)){
      const up = plotStyle(d.id) !== 'plot';
      mctx.setLineDash([3,2.5]);
      mctx.globalAlpha = up ? 0.95 : 0.5;
      mctx.strokeStyle = up ? '#000' : 'rgba(0,0,0,.34)';
      mctx.lineWidth = up ? 1.3 : 0.8;
      mctx.beginPath(); mctx.roundRect(x,y,w,h,3); mctx.stroke();
      mctx.setLineDash([]);
      mctx.fillStyle = up ? '#000' : 'rgba(0,0,0,.34)';
      mctx.font = '400 7.5px "Share Tech Mono", monospace';
      mctx.fillText(d.n, x+3, y+9.5);
      mctx.globalAlpha = 1;
      return;
    }
    const active = S.selected===d.id || S.hovered===d.id;
    const dim = d.id==='sysdig' && S.mode!=='sysdig';
    mctx.globalAlpha = dim ? 0.2 : (active ? 0.9 : 0.42);
    mctx.fillStyle = MM_FILL[d.id];
    mctx.beginPath(); mctx.roundRect(x,y,w,h,3); mctx.fill();
    mctx.globalAlpha = dim ? 0.3 : 1;
    mctx.strokeStyle = active ? '#000' : 'rgba(0,0,0,.14)';
    mctx.lineWidth = active ? 1.4 : 0.8;
    mctx.beginPath(); mctx.roundRect(x,y,w,h,3); mctx.stroke();
    mctx.globalAlpha = dim ? 0.35 : 0.85;
    mctx.fillStyle = active ? '#000' : '#535557';
    mctx.font = '400 7.5px "Share Tech Mono", monospace';
    mctx.fillText(d.n, x+3, y+9.5);
  });
  mctx.globalAlpha = 1;

  // camera position + look direction
  const cpx = mx(camera.position.x), cpz = mz(camera.position.z);
  const tx = mx(controls.target.x), tz = mz(controls.target.z);
  mctx.strokeStyle='rgba(0,0,0,.28)'; mctx.lineWidth=1;
  mctx.beginPath(); mctx.moveTo(cpx,cpz); mctx.lineTo(tx,tz); mctx.stroke();
  mctx.fillStyle='#000';
  mctx.beginPath(); mctx.arc(cpx,cpz,3.4,0,7); mctx.fill();
  mctx.fillStyle='#BDF78B';
  mctx.beginPath(); mctx.arc(tx,tz,2.4,0,7); mctx.fill();

  mctx.fillStyle='rgba(0,0,0,.32)';
  mctx.font='400 7px "Share Tech Mono", monospace';
  mctx.fillText('N ▲', 5, MM_H-6);
}
if(!CanvasRenderingContext2D.prototype.roundRect){
  CanvasRenderingContext2D.prototype.roundRect = function(x,y,w,h,r){
    this.moveTo(x+r,y); this.arcTo(x+w,y,x+w,y+h,r);
    this.arcTo(x+w,y+h,x,y+h,r); this.arcTo(x,y+h,x,y,r);
    this.arcTo(x,y,x+w,y,r); this.closePath(); return this;
  };
}


/* ============================================================
   16. HUD numbers
   ============================================================ */
const els = {
  sys:document.getElementById('mSys'), ring:document.getElementById('mRing'),
  drop:document.getElementById('mDrop'), rules:document.getElementById('mRules'),
  alert:document.getElementById('mAlert'), buried:document.getElementById('mBuried')
};
const T0 = performance.now();
let hudT = 0, lastC = {...S.counters};

/* Switching mode or scenario zeroes S.counters, and every rate here is a delta
   against the previous sample — so without dropping the baseline the first tick
   after the switch reports a large *negative* syscall rate. That is one of the
   frames a new player sees on the way in, and it reads as a broken instrument. */
function resetHudBaseline(){
  lastC = {...S.counters};
  hudT = 0;
  S.shown = {sys:0, ring:0, drop:0, rules:0, alerts:0};
  S.alertWindow = [];
}
function updateHud(dt){
  hudT += dt;
  if(hudT < 0.42) return;
  const k = 1/hudT;
  // scale the visual sim up to a plausible busy-node range (illustrative)
  const SCALE = 145;
  const sysRate  = (S.counters.sys  - lastC.sys ) * k * SCALE;
  const ringRate = (S.counters.ring - lastC.ring) * k * SCALE;
  const dropRate = (S.counters.drop - lastC.drop) * k * SCALE;
  const ruleRate = (S.counters.rules- lastC.rules)* k * SCALE;
  lastC = {...S.counters}; hudT = 0;

  /* clamped at zero: the smoothing overshoots on the way down, and a rate of
     -0.2 rendered as `0  (-0.00%)` reads as a broken instrument */
  const sm = (a,b)=> Math.max(0, a + (b-a)*0.35);
  S.shown.sys  = sm(S.shown.sys, sysRate);
  S.shown.ring = sm(S.shown.ring, ringRate);
  S.shown.drop = sm(S.shown.drop, dropRate);
  S.shown.rules= sm(S.shown.rules, ruleRate);

  const now = performance.now();
  S.alertWindow = S.alertWindow.filter(t=> now-t < 60000);
  /* alerts/min — extrapolate until a full 60s window has actually elapsed */
  const win = Math.min(60000, Math.max(5000, now - T0));
  const apm = S.alertWindow.length * (60000/win);

  const M = model();
  els.sys.textContent   = fmt(S.shown.sys);
  els.ring.textContent  = fmt(S.shown.ring);
  /* THE RATE COMES FROM THE MODEL, NOT FROM THE PARTICLE COUNTERS (GAP 6.3).
     Two bugs in one line, and both put a number on screen that disagreed with
     the number the same screen was scoring the player against:
       - the denominator was counted twice. sim.js increments `ring` when an
         event passes the kernel gate and THEN increments `drop` for the same
         event, so a dropped event is already inside `ring`; `drop/(ring+drop)`
         divides by the drops a second time.
       - it was a ratio of two EMA-smoothed rates, so the same configuration
         rendered anywhere from 14.00% to 16.30% while the scoring row sat still
         at 16.59%.
     model().dropP is the figure campaign.js scores `goal.maxDropPct` on, so
     taking it here is what makes the instrument and the scoreboard the same
     claim. The absolute events/s keeps coming from the counters — that is a
     volume, and it is honestly a smoothed one. */
  const dropPct = M.dropP * 100;
  els.drop.textContent  = fmt(S.shown.drop) + '  (' + dropPct.toFixed(2) + '%)';
  els.rules.textContent = fmt(S.shown.rules);
  els.alert.textContent = Math.round(apm);
  els.drop.className = dropPct > 0.2 ? 'red' : 'dark';

  /* the second queue. Read straight from noise() rather than smoothed, for the
     same reason the drop rate now is: this is the figure goal.maxBuriedPct is
     scored on, and an instrument that disagrees with the scoreboard is worse
     than no instrument. */
  if(els.buried){
    const Nz = noise();
    const bp = Nz.buriedP * 100;
    els.buried.textContent = bp.toFixed(2) + '%'
      + (Nz.util > 1 ? `  (${Math.round(Nz.inflow)}/${Math.round(Nz.cap)} 件/分)` : '');
    els.buried.className = bp > 0.5 ? 'red' : 'dark';
  }
  updateVerdict(M);
  maybeFitRight();
}

/* The teaching payload: name WHICH failure mode you are looking at,
   because the two have different fixes. */
const elUtil = document.getElementById('mUtil');
const elVerdict = document.getElementById('mVerdict');

/* THE BAND MUST NOT ANSWER THE SCENARIO.
 * -----------------------------------------------------------------------------
 * Two scenarios (`inherited-all-syscalls`, `slow-output`) exist to be
 * MISDIAGNOSED: you see drops, you reach for buf_size_preset, it does nothing,
 * and that is how you learn the difference between a burst and a sustained
 * overload. This band used to print the whole remedy — "バッファを増やしても
 * 直りません — base_syscalls を custom_set に絞る、…" — from the first frame
 * after entry, which denied the misdiagnosis before it could be made and left
 * those two scenarios with nothing left to diagnose.
 *
 * So each row below is split into the two things it was conflating, and they no
 * longer appear at the same time:
 *
 *   sym   the SYMPTOM. Which of the two failure modes this is, and the numbers
 *         it is measured by. Always shown — telling the two modes apart IS the
 *         skill, and a symptom is what an instrument is for.
 *   fix   WHICH LEVER MOVES IT. Explore only. Explore is the explanation of the
 *         model, there is no scenario there to spoil, and this is the one place
 *         the remedy is supposed to be readable straight off the panel.
 *
 * The third statement of the same subject — `insight.wrong` / `insight.truth`,
 * the misdiagnosis this particular situation invites — belongs to the scenario
 * file and is rendered by renderScenarioReport() only once the pass has been
 * scored. One fact, one owner, one moment each: the instrument reports, Explore
 * explains, the scenario debriefs. Before this, the band and the scenario were
 * both making the same claim, and the band was making it first. */
const VERDICT = {
  dead: {
    /* recovery is not a scenario's answer — no scenario's misdiagnosis is "the
       agent exited" — and a player with a dead agent and no way back is stuck,
       so this one sentence stays in both modes */
    sym: () => 'falco が <b>exit</b> しました。検知はゼロです。'
             + '負荷か設定を変えると再起動します。',
    fix: () => '' },
  sustained: {
    sym: M => `持続的な入力超過 — 入力は消費能力の <b>${Math.round(M.util*100)}%</b>。`
            + 'ドロップが続いています。',
    /* The advice itself was wrong twice, and it was on screen every frame:
       `cpus_for_each_syscall_buffer` is not a key that exists (it is
       `engine.<engine>.cpus_for_each_buffer`), and "set it to 1" is the
       direction the Falco docs argue AGAINST — INVARIANTS 1.4. Dropping events
       is fought by making buffers FEWER and LARGER (4–6 CPUs each, with a
       bigger preset), which is also the direction state.js §BUF_CAP now
       models, so the panel and the model finally say the same thing. */
    fix: () => '<b>バッファを細かく割っても直りません</b> — '
             + '<code>base_syscalls</code> を <code>custom_set</code> に絞って入力を減らす、'
             + '<code>engine.&lt;engine&gt;.cpus_for_each_buffer</code> を <b>4</b> に上げて'
             + '（バッファは少なく大きく）<code>buf_size_preset</code> と組ませる、'
             + 'slow output を外す。' },
  burst: {
    sym: M => 'バースト起因のドロップ。平均は消費能力の内側'
            + `（<b>${Math.round(M.util*100)}%</b>）で、山だけが溢れています。`,
    fix: () => '平均は足りているので <code>buf_size_preset</code> を上げれば効きます。' },
  ok: {
    sym: () => 'ドロップなし。消費が入力に追いついています。',
    fix: () => '' }
};

function verdictKind(M){
  if(S.dead) return 'dead';
  if(M.sustained > 0.004) return 'sustained';
  if(M.burst > 0.0015) return 'burst';
  return 'ok';
}

function updateVerdict(M){
  elUtil.textContent = Math.round(M.util*100)+'%';
  elUtil.className = M.util > 1 ? 'red' : 'dark';
  const cls = verdictKind(M);
  const v = VERDICT[cls];
  /* GAME.on is the whole gate: in a scenario the band reports, in Explore it
     also explains. Nothing else about the band changes between the two. */
  const fix = GAME.on ? '' : v.fix(M);
  elVerdict.className = 'verdict ' + cls;
  elVerdict.innerHTML = v.sym(M) + (fix ? ' ' + fix : '');
}
function fmt(n){
  if(n >= 1e6) return (n/1e6).toFixed(2)+'M';
  if(n >= 1e3) return (n/1e3).toFixed(1)+'k';
  return Math.round(n).toString();
}

/* ============================================================
   18. sound switch
   ------------------------------------------------------------
   The whole point of this control is *where the call happens*: an AudioContext
   may only be created inside a real user gesture, so setMuted(false) runs in
   the click handler itself and nowhere else. Default is off, so silence is the
   correct state — what has to work is being able to turn it on.
   ============================================================ */
const elSnd = document.getElementById('soundSeg');
function renderSound(){
  const on = !audioState().muted;
  elSnd.querySelectorAll('button').forEach(b =>
    b.classList.toggle('on', (b.dataset.snd === 'on') === on));
}
if(elSnd){
  elSnd.querySelectorAll('button').forEach(b => b.onclick = ()=>{
    setMuted(b.dataset.snd !== 'on');   /* creates the context, in this gesture */
    initAudio();                        /* and resumes it if it was suspended */
    renderSound();
  });
  renderSound();
  /* The returning visitor whose saved preference is "on" still has no context:
     it cannot exist before they touch something. One gesture, once. */
  addEventListener('pointerdown', function armAudio(){
    removeEventListener('pointerdown', armAudio, true);
    initAudio();
  }, true);
}

/* The entrance goes up last, so the button it adds to #uiModeSeg is wired after
   the handlers above have already claimed that segment. */
initMenu();

